for entity_name in "MEMO" "USER" "ATTACHMENT" "INBOX" "IDP"; do
  case "$entity_name" in
    MEMO) pattern='store\.\(Memo\b\|FindMemo\b\|DeleteMemo\b\|UpdateMemo\b\|FindMemoPayload\b\|Visibility\b\|RowStatus\b\)' ;;
    USER) pattern='store\.\(User\b\|FindUser\b\|UpdateUser\b\|DeleteUser\b\|DeleteUserResult\b\|UserSetting\b\|FindUserSetting\b\|UserIdentity\b\|FindUserIdentity\b\)' ;;
    ATTACHMENT) pattern='store\.\(Attachment\b\|FindAttachment\b\|UpdateAttachment\b\|DeleteAttachment\b\)' ;;
    INBOX) pattern='store\.\(Inbox\b\|FindInbox\b\|UpdateInbox\b\|DeleteInbox\b\)' ;;
    IDP) pattern='store\.\(IdentityProvider\b\|FindIdentityProvider\b\|UpdateIdentityProvider\b\|DeleteIdentityProvider\b\)' ;;
  esac
  dirs=$(grep -rn "$pattern" --include="*.go" | grep -v "^store/" | grep -v "_test.go" | sed 's|^\([^:]*\)/[^/]*:.*|\1|' | sort -u)
  count=$(echo "$dirs" | grep -c . 2>/dev/null || echo 0)
  echo "$entity_name: $count distinct packages"
done

